from taf.collectors.kubernetes.factory import KubernetesCollectorFactorySelector
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class kubernetes(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_kubernetes_collector(self, name,
                                    pod_name,
                                    executor,
                                    namespace,
                                    container=None,
                                    merge_container_logs=None,
                                    target_file_name=None,
                                    sudo_password=None,
                                    ):
        """
        Create Kubernetes Collector from given configuration.

        :param str name: name of collector
        :param str pod_name: name of pod
        :param dict executor: setup info host, user, password
        :param str namespace:  name of namespace
        :param str container: (optional) container name, default: all containers of the pod
        :param bool merge_container_logs: (optional) If True, logs from all containers will be merged into one log
                                          default value: False, multiple logs will get created one per container
                                          (setting this parameter to True/False is not allowed, when a container is given)
        :param str target_file_name: (optional) file_name.tgz format, its part of the path under which kubernetes log
                                     file stored locally during collect_collectors
                                     default value: "kubernetes_log.tgz"
        :param str sudo_password: (optional) sudo password for some command need root permission
                default value: None
        :return: None
        """
        assert merge_container_logs is None or container is None, \
            "merge_container_logs must not be given, if a container is given"
        configuration = {'name': name, 'executor': executor, 'pod_name': pod_name, 'namespace': namespace}
        if container is not None:
            configuration["container"] = container
        if sudo_password is not None:
            configuration["sudo_password"] = sudo_password
        if target_file_name is not None:
            configuration["target_file_name"] = target_file_name
        configuration["merge_container_logs"] = merge_container_logs or False
        logger.info("Creating Kubernetes Collector with alias name " + name)
        kubernetes_collector = KubernetesCollectorFactorySelector().create(configuration=configuration,
                                                                           existing_arguments={})
        logger.info("Kubernetes Collector created successfully")
        self.set_alias(name, kubernetes_collector)
